// the build-up: the theme's opening over B♭ – C, a run up from the dominant, a trill on it
const RUN = [
  [0, 10, 0.5], [0.5, 12, 0.25], [0.75, 10, 0.5], [1.25, 12, 0.75], [2, 14, 0.5], [2.5, 16, 0.5], [3, 14, 0.75], [3.75, 16, 0.25],
  [4, 16, 0.75], [4.75, 17, 0.5], [5.25, 17, 0.75], [6, 16, 1], [7, 14, 0.5], [7.5, 16, 0.5],
  [8, 9, 0.5], [8.5, 10, 0.5], [9, 13, 0.5], [9.5, 14, 0.5], [10, 16, 0.5], [10.5, 17, 0.5], [11, 19, 0.5], [11.5, 21, 0.5],
  [12, 21, 0.25], [12.25, 22, 0.25], [12.5, 21, 0.25], [12.75, 22, 0.25], [13, 21, 0.25], [13.25, 22, 0.25], [13.5, 21, 0.25], [13.75, 22, 0.25], [14, 21, 0.25], [14.25, 22, 0.25], [14.5, 21, 0.25], [14.75, 22, 0.25], [15, 21, 0.25], [15.25, 22, 0.25], [15.5, 21, 0.25], [15.75, 22, 0.25],
]
// the solo: a random walk over the scale, chord tones on the beats (improvise)
const SOLO = improvise({
  start: 112, length: 62, rate: 2, seed: 295, swing: SW, lo: 5, hi: 24,
  phrase: 8, rest: 0.2, hold: 0.3, scale: () => SCALE, chord: x => (chordAt(x)?.[3] ?? [0]).map(n => mod(n, 12)),
}).map(([b, n, d]) => [b - 112, n, d])
const PHRASES = { A: THEME_A, B: THEME_B, BRIDGE, REST, SOLO, RUN }

// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[16,"REST",0,1],[48,"A",0,1],[64,"A",0,1],[80,"A",0,1],[96,"A",0,1],[112,"REST",0,1],[176,"A",0,1],[192,"REST",0,1],[208,"A",1,1],[224,"A",1,1],[240,"A",1,1],[256,"A",1,1],[272,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[16,"B",0,1],[32,"B",0,1],[48,"REST",0,1],[112,"SOLO",0,1],[176,"REST",0,1],[192,"RUN",0,1],[208,"REST",0,1],[272,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[16,"REST",0,1],[48,"REST",0,1],[112,"REST",0,1],[176,"REST",0,1],[192,"REST",0,1],[208,"HARMONY",0,1],[272,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- moog --------------------------------------------------------------------------------------
const track0 = {
  color: '#ffd166',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["Mg = \\Rev\\,\\Dly\\Big[\\tfrac1d\\tanh\\!\\Big(d\\,\\LP^{Q=2.2}_{f_c}\\LP_{f_c}\\big(\\tfrac12\\saw g + \\tfrac12\\saw 1.0052g + 0.4\\sq\\tfrac g2\\big)\\Big)\\Big],\\quad f_c = 700 + 4200v\\,e^{-t/0.18}\\quad\\text{— «Муг»}"],
  audio({ bpm }) {
    const sec = 60 / bpm, s = monoSynth({ cutoff: 700, env: 4200, res: 2.2, decay: 0.18, glide: 18, sub: 0.4, drive: 2 })
    const echo = delay({ time: sec * 0.5, feedback: 0.25, wet: 0.16 }), verb = reverb({ room: 0.75, damp: 0.45, wet: 0.2 })
    let n = 0
    return x => {
      const m = leadAt(x), t = x * sec
      if (m) n = m.n
      const vib = m && m.τ * sec > 0.35 ? 0.2 * sin(TAU * 5.6 * t) : 0
      return verb(...echo(...pan(0.72 * s(hz(n + vib, C4), !!m && m.u < 0.9, 0.9) * pumpAt(x), 0.12)))
    }
  },
}

// ---- epiano ------------------------------------------------------------------------------------
const track1 = {
  color: '#ffcf9f',
  graph: x => { const m = lead2At(x); return m ? 1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = lead2At(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["E(f,t,v) = v\\Big(\\sin\\!\\big(2\\pi ft + (0.5+1.8v^2)e^{-4t}\\sin 2\\pi ft\\big)\\,e^{-t/(1+250/f)} + 0.2v\\,e^{-35t}\\sin 2\\pi\\,14ft\\Big)"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = poly(epianoTone, { release: 0.35, life: 6 }), fire = trigger(), echo = delay({ time: sec * 0.75, feedback: 0.32, wet: 0.22 }), verb = reverb({ room: 0.85, wet: 0.33 })
    return x => {
      const m = lead2At(x)
      if (fire(m ? m.at : null)) p.hit(hz(m.n, C4), 0.7 + 0.2 * hash(floor(4 * x), 3), m.d * sec + 0.35)
      const y = 0.234 * p()
      return verb(...echo(...pan(y, -0.3)))
    }
  },
}

