// ---- funkguitar --------------------------------------------------------------------------------
const track3 = (() => {
  const SCRATCH = { 0: 'X---------------', 1: 'X-----x-X-----x-', 2: 'X-xX-xX-x-X-xX-x', 3: 'X-xXx-X-xX-xX-xX' }
  const guitarAt = x => {
    const c = chordAt(x), e = energy(x)
    if (!c || e < 0 || role(x) === 'build' || x >= END - 1) return null
    const j = floor(4 * x + 1e-9), s = SCRATCH[e][mod(j, 16)]
    return s === '-' ? null : { at: j / 4, dead: s === 'x', up: j % 2 === 1, c }
  }
  return {
  color: '#ffcf9f',
  graph: x => { const g = guitarAt(x); return g && !g.dead ? g.c[3].map(n => -1 + (n - 48) / 20) : null },
  midi: x => { const g = guitarAt(x); return g && !g.dead && x - g.at < 0.2 ? g.c[3] : [] },
  formula: ["G = \\Rev\\,\\Cho\\Big[0.8\\LP_{5.5\\text{к}}s + 0.45\\BP_{2.3\\text{к}}s\\Big],\\ s = \\HP_{160}\\sum_{j}\\text{струна}_j\\big(f_j,\\ t - 7j\\,\\text{мс}\\big)\\quad\\text{(Карплус — Стронг, точный строй)}","\\text{шестнадцатые: X — аккорд, приглушённый через } \\tfrac{1}{10}\\text{ доли; x — «чик» глушёных струн}"],
  audio({ bpm }) {
    const sec = 60 / bpm, g = funkGuitar({ seed: 7 }), fire = trigger(), ch = chorus({ mix: 0.3, rate: 0.7 }), verb = reverb({ room: 0.6, damp: 0.5, wet: 0.16 })
    let last = null
    return x => {
      const h = guitarAt(x)
      if (h && fire(h.at)) {
        g.strum([h.c[2] + 12, ...h.c[3]].map(n => hz(n - 60, C4)), (h.dead ? 0.45 : 0.75) * (0.9 + 0.1 * hash(floor(4 * x), 2)), { up: h.up, dead: h.dead })
        last = h.dead ? null : h.at
      }
      if (last != null && x - last > 0.1) (g.mute(0.02), (last = null))
      return verb(...ch(...pan(0.85 * g(), -0.35)))
    }
  },
}})()

// ---- strings -----------------------------------------------------------------------------------
const track4 = {
  color: '#d9b8ff',
  graph: x => (padOn(x) ? chordAt(x)[3].map(n => -1.7 + (n - 48) / 30) : null),
  midi: x => (padOn(x) && mod(x, 4) < 3.9 ? chordAt(x)[3].map(n => n - 12 * (n > 64)) : []),
  formula: ["S = \\Rev\\,\\Cho\\,\\LP\\,\\HP\\sum_{j}\\sum_{u=-1}^{1}\\saw\\!\\Big(f_j\\,2^{\\,(0.09u + 0.12\\sin 2\\pi r_{j,u}T)/12}\\Big)"],
  audio() {
    const s = strings({ voices: 4, attack: 700, release: 1400, cutoff: 2600, gain: 0.054 }), ch = chorus({ mix: 0.4 }), verb = reverb({ room: 0.9, wet: 0.45 })
    return x => {
      const [l, r] = s(padOn(x) ? chordAt(x)[3].map(n => hz(n - 60 - 12 * (n > 64), C4)) : []), d = pumpAt(x)
      return verb(...ch(d * l, d * r))
    }
  },
}

